    add(4, "th",
        title="แรงกำและคะแนนการเคลื่อนไหวหลังโรคหลอดเลือดสมอง: การศึกษาแบบสุ่มของถุงมือฝึกแบบหุ่นยนต์",
        desc="SPORT TK ปี 2025 ผู้เข้าร่วม 30 คน ความต่างเฉลี่ยที่รายงาน: แรงกำ 1.87 (95% CI 0.39–3.35, P=0.015) และ Fugl-Meyer 16.67 (95% CI 3.9–29.4, P=0.012) ไม่ได้ระบุรุ่น",
        lead="หลังโรคหลอดเลือดสมอง แพทย์มักแบ่งมือเป็นสองปัญหาที่ใช้ได้จริง คือกำได้หรือไม่ และขยับอย่างควบคุมได้หรือไม่ การศึกษาแบบสุ่มปี 2025 ใน SPORT TK-EuroAmerican Journal of Sport Sciences วัดทั้งสอง บทความรายงานความต่างเฉลี่ยระหว่างกลุ่มอย่างมีนัยสำคัญทางสถิติที่เอื้อต่อถุงมือฝึกแบบหุ่นยนต์ ทั้งแรงกำและคะแนนการเคลื่อนไหว Fugl-Meyer มีผู้เข้าร่วม 30 คน และบทความไม่ได้ระบุรุ่นเชิงพาณิชย์",
        bg=[
            "แรงกำที่เปลี่ยนไม่จำเป็นต้องเกิดเป็นการเคลื่อนไหวที่ใช้ได้ และคะแนนการเคลื่อนไหวที่สูงขึ้นไม่ได้แปลว่าคนยกถ้วยได้ การวัดแรงและการเคลื่อนไหวในการเปรียบเทียบแบบสุ่มเดียวกัน ช่วยไม่ให้ตีพิมพ์เฉพาะด้านที่ดูดีกว่า",
            "บทความเรื่องถุงมือมักละรุ่นไว้ ถ้าไม่มีรุ่น ผลจะคัดลอกลงสเปกผลิตภัณฑ์ไม่ได้ บทสรุปนี้จึงอยู่กับความต่างที่บทความให้จริง",
        ],
        device="",
        design="การเปรียบเทียบแบบสุ่มระหว่างการฝึกด้วยถุงมือฝึกแบบหุ่นยนต์กับเงื่อนไขควบคุม ผลลัพธ์ร่วมคือแรงกำและคะแนนการเคลื่อนไหว Fugl-Meyer รายงานเป็นความต่างเฉลี่ยพร้อมช่วงเชื่อมั่น 95%",
        sample="คนหลังโรคหลอดเลือดสมอง 30 คน กลุ่มละ 15 บทความไม่ได้ระบุรุ่นที่วางตลาด ภาพถุงมือทั่วไปเป็นภาพประกอบ ไม่ใช่การระบุอุปกรณ์",
        result="ความต่างเฉลี่ยระหว่างกลุ่มที่รายงานคือแรงกำ 1.87 (95% CI 0.39 ถึง 3.35, P=0.015) และ Fugl-Meyer 16.67 (95% CI 3.9 ถึง 29.4, P=0.012) ความต่างเฉลี่ยไม่ใช่พัฒนาการของแต่ละคน ช่วงของคะแนนการเคลื่อนไหวกว้าง ซึ่งเป็นภาพของกลุ่มตัวอย่างเล็กเมื่อค่าประมาณไม่ละเอียด",
        sig=[
            "การเผยทั้งความต่างและช่วงมีประโยชน์กว่าประโยค «ดีกว่ากลุ่มควบคุม» ทิศทางเห็นได้ และความไม่แน่นอนก็เห็นได้",
            "เพราะไม่ได้ระบุรุ่น ผลนี้เล่าต่อเป็นสเปกหรือข้อบ่งใช้ของถุงมือ Syrebo รุ่นใดรุ่นหนึ่งไม่ได้ สามสิบคนยังเหลือที่ให้สัญญาณรบกวนจากการสุ่มตัวอย่าง",
        ],
        limit="กลุ่มตัวอย่างเล็ก (n=30) ไม่ได้ระบุรุ่น และภาพไม่ใช่การจับคู่ ความต่างเฉลี่ยและค่า P เป็นสถิติของการศึกษา")

    add(5, "th",
        title="การทำงานของมือในระยะกึ่งเฉียบพลันต้น: RCT นำร่องแบบปกปิดทางเดียวของ SY-HR03E โดยทีมหัวซาน",
        desc="RCT นำร่องแบบปกปิดทางเดียวใน BioMedical Engineering OnLine ผู้ป่วยใน 20 คน SY-HR03E สี่สัปดาห์ บทความรายงานว่าทำครบ ไม่มีเหตุไม่พึงประสงค์ และมีสัญญาณเบื้องต้นในคะแนนมือกับกิจกรรมประจำวัน",
        lead="ในระยะกึ่งเฉียบพลันต้น คำถามแรกไม่ใช่ว่าคะแนนจะขึ้นกี่จุด แต่คือเซสชันทำจนจบได้หรือไม่ และปลอดภัยหรือไม่ ทีมที่นำโดยศาสตราจารย์ Jia Jie ที่โรงพยาบาลหัวซาน มหาวิทยาลัยฟู่ตั้น เผยแพร่ใน BioMedical Engineering OnLine การศึกษาแบบสุ่มนำร่องปกปิดทางเดียวเรื่อง Syrebo SY-HR03E สำหรับการฟื้นฟูมือในช่วงนั้น บทความรายงานว่าผู้เข้าร่วมทั้ง 20 คนทำครบสี่สัปดาห์ ไม่มีผู้ถอนตัวและไม่มีเหตุไม่พึงประสงค์ คะแนนมือดีขึ้นทั้งสองกลุ่ม โดยกลุ่มถุงมือเปลี่ยนมากกว่า การเปลี่ยนแปลงภายในกลุ่มของกิจกรรมประจำวันถึงนัยสำคัญทางสถิติในกลุ่มถุงมือ",
        bg=[
            "แขนและมือมักฟื้นช้ากว่าการเดิน การกิน การแต่งตัว และการล้างหน้าอาศัยการขยับนิ้วที่แยกส่วน ไม่ใช่ตัวเลขแรงตัวเดียว การบำบัดมือแบบเดิมช่วยได้ แต่จำนวนครั้งที่นักบำบัดทำให้มีจำกัด และการเคลื่อนไหวเดียวกันทำซ้ำข้างเตียงได้ยาก",
            "ถุงมือลมสามารถงอและเหยียดนิ้วโดยมีมวลบนมือน้อย จึงมีการพูดถึงการใช้ข้างเตียง คนในระยะกึ่งเฉียบพลันต้นยังฟื้นเองด้วย «ผลเบื้องต้น» ใดต้องอ่านบนพื้นหลังนั้น การศึกษาแบบสุ่มนำร่องมีไว้แสดงว่าแผนทำได้ และทิ้งสัญญาณให้การศึกษาที่ใหญ่กว่า ไม่ได้แทนการศึกษาเพื่อยืนยัน",
        ],
        device="บทความบรรยาย SY-HR03E ว่าเป็นถุงมือแบบนิ่มเชิงพาณิชย์พร้อมเครื่องควบคุมบนโต๊ะ มวลที่รายงานประมาณ 3.5 กิโลกรัมสำหรับระบบ และประมาณ 110 กรัมสำหรับถุงมือ  ท่อลูกฟูกแบบลมที่หลังมือช่วยงอและเหยียด เซนเซอร์ความดันดูการเปลี่ยนแปลงเมื่อคนพยายามขยับ เมื่อเกินเกณฑ์ที่ตั้งไว้ 0.7 kPa เครื่องควบคุมถือว่าเป็นการตั้งใจเคลื่อนไหว แล้วเติมหรือปล่อยลม โหมดที่ตั้งใจคือการช่วยแบบแอ็กทีฟ ไม่ใช่การดึงที่รับทั้งหมด",
        design="การสุ่มนำร่องแบบปกปิดทางเดียว กลุ่มหุ่นยนต์เพิ่มการแบและกำที่ถุงมือช่วยเข้ากับการฟื้นฟูมาตรฐาน กลุ่มเดิมได้รับการบำบัดมือแบบดั้งเดิมที่มีความยาวเซสชันเท่ากัน ทั้งสองกลุ่มยังได้รับการฟื้นฟูมาตรฐานวันละหนึ่งชั่วโมง นักบำบัดกำกับท่า ทะเบียน ChiCTR2000034614",
        sample="ผู้ป่วยใน 20 คน ตั้งแต่ 7 วันถึง 3 เดือนหลังเริ่มเป็น กลุ่มละ 10 เซสชันถุงมือวันละ 30 นาที ห้าวันต่อสัปดาห์ สี่สัปดาห์ การแบ-กำแต่ละครั้งค้างประมาณสามวินาที สังกัดผู้เขียนรวมทีมคลินิก และตามที่บทความเปิดเผย Shanghai Siyi Intelligent Technology ความสัมพันธ์นั้นเป็นส่วนหนึ่งของการอ่าน",
        result="บทความรายงานว่าทั้ง 20 คนทำครบสี่สัปดาห์ ไม่มีผู้ถอนตัวและไม่มีเหตุไม่พึงประสงค์ คะแนน Fugl-Meyer ของมือดีขึ้นทั้งสองกลุ่ม โดยกลุ่มหุ่นยนต์ดีขึ้นมากกว่า ในดัชนี Barthel ฉบับปรับ มีเพียงการเปลี่ยนแปลงภายในกลุ่มของกลุ่มหุ่นยนต์ที่รายงานว่ามีนัยสำคัญทางสถิติ (p<0.001) การเปลี่ยนแปลงภายในกลุ่มเดิมไม่มีนัยสำคัญ ระยะ Brunnstrom ของมือก็แสดงการเปลี่ยนแปลงภายในกลุ่มอย่างมีนัยสำคัญเฉพาะกลุ่มหุ่นยนต์ ในงานนำร่อง 10 ต่อ 10 ค่า P ภายในกลุ่มเป็นสัญญาณ ไม่ใช่หลักฐานว่าการทำงานประจำวันจะสูงขึ้นในผู้ป่วยทั่วไป",
        sig=[
            "การศึกษาถุงมือแบบนิ่มจำนวนมากรับคนในระยะเรื้อรัง งานนำร่องนี้ย้ายคำถามเรื่องความเป็นไปได้และความปลอดภัยไปที่ช่วง 7 วันถึง 3 เดือน ไม่ได้ย้ายข้ออ้างเรื่องประสิทธิผลระยะเรื้อรังมาเร็วขึ้น",
            "คะแนนมือกับคะแนนกิจกรรมประจำวันไม่ได้มีรูปทางสถิติแบบเดียวกัน บทความรายงานการเปลี่ยนแปลง Barthel ภายในกลุ่มอย่างมีนัยสำคัญเฉพาะกลุ่มถุงมือ การแยกนี้ควรทดสอบอีกครั้ง ไม่ใช่คำกล่าวว่ากิจกรรมในชีวิตประจำวันถูกแก้แล้ว ถุงมือ 110 กรัมและการตรวจจับความตั้งใจทำให้พูดถึงการใช้ข้างเตียง และภายหลังที่บ้าน ได้ การศึกษานี้เองทำในผู้ป่วยใน",
        ],
        limit="การสุ่มนำร่อง กลุ่มละ 10 สัญญาณเบื้องต้นต้องการกลุ่มตัวอย่างใหญ่กว่า ค่า P เป็นรายงานของบทความสำหรับผลลัพธ์นั้น มีการเปิดเผยสังกัดที่เกี่ยวกับอุปกรณ์และควรชั่งน้ำหนัก")

    add(6, "th",
        title="ความบกพร่องของมือแบบเสมหะอุดกั้น: การศึกษาสี่แขน 200 คนของถุงมือร่วมไฟฟ้าฝังเข็ม",
        desc="Journal of Hunan University of Chinese Medicine ผู้เข้าร่วม 200 คน สี่แขน อัตราได้ผลรวมที่รายงานคือ 88%, 76%, 77.6% และ 70.8% ตัวเลขเหล่านี้เป็นดัชนีรวมของการศึกษา ไม่ใช่อัตราของผลิตภัณฑ์",
        lead="การใส่ถุงมือหุ่นยนต์กับไฟฟ้าฝังเข็มในแผนเดียวกันเป็นทางเลือกบูรณาการที่เฉพาะ และผลต้องติดอยู่กับแขนที่ทำให้เกิดผลนั้น การศึกษาสี่แขนปี 2022 ใน Journal of Hunan University of Chinese Medicine รับคน 200 คนที่มีความบกพร่องของมือหลังโรคหลอดเลือดสมองแบบ phlegm-stasis blocking collaterals และเปรียบเทียบถุงมือร่วมไฟฟ้าฝังเข็ม ถุงมืออย่างเดียว ไฟฟ้าฝังเข็มอย่างเดียว และการฟื้นฟูตามปกติ «อัตราได้ผลรวม» ของบทความเองคือ 88%, 76%, 77.6% และ 70.8% ดัชนีรวมนี้เป็นบทสรุปของผู้เขียน ไม่ใช่อัตราประสิทธิผลของผลิตภัณฑ์",
        bg=[
            "ภายใต้การวินิจฉัยแบบนี้ ทางเดินมักรวมการฟื้นฟูสมัยใหม่กับไฟฟ้าฝังเข็ม ผังสี่แขนแสดงการร่วมกัน อุปกรณ์อย่างเดียว การฝังเข็มอย่างเดียว และการดูแลตามปกติบนมาตราเดียวกัน แทนเรื่องก่อน-หลังที่ไม่มีคู่เปรียบ",
            "อัตราได้ผลรวมยุบหลายการตัดสินเป็นร้อยละเดียว ใช้ได้กับความต่างหยาบ และใช้ไม่ได้เป็นการเปลี่ยนแปลงของคนหนึ่งบนมาตราที่มีชื่อ อ้างเป็น «ประสิทธิผลของถุงมือคือ 88%» ไม่ได้",
        ],
        device="",
        design="สี่แขน: ถุงมือหุ่นยนต์ร่วมไฟฟ้าฝังเข็ม ถุงมืออย่างเดียว ไฟฟ้าฝังเข็มอย่างเดียว และการฟื้นฟูตามปกติ ผลที่พูดถึงที่นี่คืออัตราได้ผลรวมของบทความ สังกัดรวม Shanghai Siyi Intelligent Technology โดย Yin Ganggang เป็นผู้เขียนร่วม การเปิดเผยนี้อยู่กับการอ่าน",
        sample="คน 200 คนที่มีความบกพร่องของมือหลังโรคหลอดเลือดสมองแบบ phlegm-stasis blocking collaterals นี่เป็นกลุ่มตัวอย่างใหญ่สุดในคอลัมน์ บทความไม่ได้ระบุรุ่นที่จับคู่ผลิตภัณฑ์ปัจจุบันได้ และภาพทั่วไปไม่ใช่การจับคู่นั้น",
        result="อัตราได้ผลรวมที่รายงานคือ 88% สำหรับถุงมือร่วมไฟฟ้าฝังเข็ม, 76% สำหรับถุงมืออย่างเดียว, 77.6% สำหรับไฟฟ้าฝังเข็มอย่างเดียว และ 70.8% สำหรับการฟื้นฟูตามปกติ ดัชนีรวมที่สูงกว่าในแขนร่วมหมายความเพียงว่า ภายใต้กติกาของการศึกษานี้ แขนนั้นได้คะแนนสูงกว่า ไม่ได้มอบ 88% ให้ถุงมือ และ 76% ไม่ใช่อัตราผลิตภัณฑ์ ตัวเลขของถุงมืออย่างเดียวกับไฟฟ้าฝังเข็มอย่างเดียวอยู่ใกล้กัน ซึ่งก็ค้านการอธิบายรูปแบบทั้งหมดด้วยองค์ประกอบเดียว",
        sig=[
            "สองร้อยคนและสี่แขนให้ดัชนีรวมที่เปรียบเทียบได้ ไม่ใช่ร้อยละสำหรับหน้าผลิตภัณฑ์ เมื่ออ่านเป็นอัตราได้ผลรวม ช่องว่างระหว่างการร่วมกัน วิธีเดี่ยว และการดูแลตามปกติมีจำกัด",
            "บทความตามที่สรุปที่นี่ไม่ได้ให้ความต่างเฉลี่ยแบบเดียวกับการศึกษาอื่นในคอลัมน์ จนกว่ามาตราเหล่านั้นจะอยู่บนโต๊ะ การศึกษานี้เป็นเรื่องว่าองค์ประกอบถูกรวมอย่างไร ไม่ใช่ว่าคะแนนมือจะขึ้นกี่จุด",
        ],
        limit="ร้อยละเป็นอัตราได้ผลรวมของการศึกษาเอง แขนร่วมไม่สามารถโยงให้ถุงมือหรือไฟฟ้าฝังเข็มอย่างเดียว ไม่ได้ระบุรุ่น")

    add(7, "th",
        title="การฟื้นฟูมือหลังกล้ามเนื้อสมองตายในเขตหลอดเลือดสมองกลาง: รายงานผู้ป่วยหญิงอายุ 66 ปี",
        desc="รายงานผู้ป่วยใน Cureus หญิง 66 ปีที่มีกล้ามเนื้อสมองตายสองข้างในเขต MCA ได้รับโปรแกรมถุงมือ Syrebo ภายใต้การกำกับทางคลินิก รายเดียวไม่ใช่ผลทั่วไป",
        lead="การศึกษาแบบสุมอธิบายความต่างเฉลี่ย รายงานผู้ป่วยอธิบายว่าการฟื้นฟูถูกจัดให้คนหนึ่งอย่างไร ปี 2024 ใน Cureus Sharma และคณะรายงานหญิง 66 ปีที่มีกล้ามเนื้อสมองตายในเขตหลอดเลือดสมองกลาง ซึ่งได้รับประสาทกายภาพบำบัดที่สร้างรอบโปรแกรมถุงมือ Syrebo รายงานติดตามลำดับการสังเกตและการเปลี่ยนแปลงการทำงาน เป็นรายเดียวและไม่นำไปใช้ทั่วไป",
        bg=[
            "กล้ามเนื้อสมองตายในเขตนี้มักกระทบแขนและมือพร้อมภาษาหรือการรู้คิด แผนจึงมากกว่ามือที่อ่อนแรง ครอบครัวมักต้องรู้ว่าการฝึกถุงมืออยู่ตรงไหนในการกายภาพบำบัด และใครกำกับ มากกว่าต้องการร้อยละ",
            "รายงานผู้ป่วยเขียนลำดับนั้นได้ ไม่มีกลุ่มควบคุมขนาน ดังนั้นการเปลี่ยนก่อน-หลังใดปนการฟื้นเอง การดูแลตามปกติ และถุงมือ ชิ้นเหล่านี้แยกไม่ได้",
        ],
        device="บทความพูดถึงโปรแกรมถุงมือ Syrebo และไม่ได้ระบุรุ่น ภาพถุงมือและเครื่องควบคุมคือรูปที่ 2 ของรายงานเปิดเสรีนั้น (CC BY 4.0) แสดงในข้อความตอนต้น ไม่ใช่รูปจากบทปริทัศน์อื่น",
        design="รายงานรายเดียว ไม่ใช่การศึกษาแบบสุ่ม หลังจากคนนั้นคงที่ทางการแพทย์ แพทย์ให้ประสาทกายภาพบำบัดที่รวมโปรแกรมถุงมือ Syrebo",
        sample="หญิง 66 ปีที่มีกล้ามเนื้อสมองตายสองข้างในเขต MCA รายงานบันทึกการสังเกตและการเปลี่ยนแปลงการทำงาน ไม่มีสถิติระหว่างกลุ่ม",
        result="คุณค่าของรายงานคือลำดับการดูแล ไม่ใช่อัตราการดีขึ้น แสดงว่าถุงมือแบบนิ่มถูกวางในการฟื้นฟูของคนหนึ่งที่มีกล้ามเนื้อสมองตายรุนแรง ภายใต้การกำกับของผู้ประกอบวิชาชีพ การเปลี่ยนแปลงในรายเดียวไม่ใช่ระดับการฟื้นตัวที่รับประกัน",
        sig=[
            "ในคอลัมน์ที่ส่วนใหญ่เป็นการศึกษาแบบสุ่ม รายงานผู้ป่วยหนึ่งเรื่องอยู่ที่นี่เพื่อแสดงว่าโปรแกรมถูกใช้กับคนอย่างไร เติมช่องว่างเชิงเรื่องเล่า ไม่ได้ยกระดับหลักฐาน",
            "รายเดียวประมาณความบ่อยของเหตุไม่พึงประสงค์ไม่ได้ และบอกไม่ได้ว่าระยะเฉียบพลัน กึ่งเฉียบพลัน หรือเรื้อรังเหมาะกว่า คำถามเหล่านั้นอยู่กับการศึกษาที่มีกลุ่มควบคุม",
        ],
        limit="รายเดียว ไม่ใช่ผลทั่วไป การเปลี่ยนแปลงการทำงานโยงให้ถุงมืออย่างเดียวไม่ได้")

    add(8, "th",
        title="ความบกพร่องของแขนหลังโรคหลอดเลือดสมอง: การศึกษาแบบสุ่ม 60 คนเรื่องการบำบัดด้วยกระจกแบบใหม่",
        desc="New Medicine ปี 2024 คน 60 คน สี่สัปดาห์ บทความรายงานพัฒนาการที่มากกว่าใน FMA-UE, FMA-WH และดัชนี Barthel ฉบับปรับ เมื่อใช้การบำบัดด้วยกระจกแบบใหม่เทียบแบบเดิม",
        lead="การบำบัดด้วยกระจกแบบเดิมใช้กระจกเพื่อให้ดูเหมือนมือข้างที่ได้รับผลกำลังขยับ แบบใหม่ให้ถุงมือหุ่นยนต์พามือข้างที่ได้รับผลผ่านการกระทำเดียวกับที่กระจกแสดง เพื่อให้การเห็นและการทำอยู่ในเซสชันเดียวกัน ปี 2024 New Medicine เผยแพร่การศึกษาแบบสุ่มของ Chen และคณะ ที่เปรียบเทียบสองแบบใน 60 คนเป็นเวลาสี่สัปดาห์ บทความรายงานพัฒนาการที่มากกว่าของการบำบัดด้วยกระจกแบบใหม่ในการเคลื่อนไหวของแขน การเคลื่อนไหวข้อมือ-มือ และกิจกรรมประจำวัน",
        bg=[
            "การบำบัดด้วยกระจกมีขีดจำกัดที่รู้กัน ถ้ามือข้างที่ได้รับผลไม่ขยับ ข้อเสนอทางภาพก็ไม่มีข้อมูลการเคลื่อนไหวคู่กัน การเชื่อมการงอและเหยียดที่ช่วยเข้ากับงานกระจก เป็นความพยายามให้ด้านที่ได้รับผลทำการเคลื่อนไหวจนจบจริงในช่วงที่นักบำบัดกำหนด",
            "การเปลี่ยนแปลงนั้นจะปรากฏบนคะแนนหรือไม่ ต้องทดสอบเทียบการบำบัดด้วยกระจกแบบเดิม ไม่ใช่เทียบกับการไม่ทำอะไร หกสิบคนที่แบ่งเท่ากันเป็นขนาดแบบสุ่มขั้นต้น",
        ],
        device="ภาพฝึกบนหน้าวารสารแสดงเครื่องหมาย Yisheng (羿生) คอลัมน์จับคู่เครื่องหมายนั้นกับ SY-HR08E ในเอกสารทางการ และแสดงภาพผลิตภัณฑ์ที่มีจอ เครื่องควบคุม และถุงมือ การจับคู่เป็นบันทึกเพื่อระบุ ไม่ใช่การอ้างรุ่นที่พิมพ์เหมือนทะเบียนการศึกษา",
        design="การจัดสรรด้วยเลขสุ่ม การบำบัดด้วยกระจกแบบใหม่ ซึ่งรวมงานกระจกกับถุงมือหุ่นยนต์ ถูกเทียบกับการบำบัดด้วยกระจกแบบเดิม ผลลัพธ์รวม FMA-UE, FMA-WH และดัชนี Barthel ฉบับปรับ",
        sample="คนที่มีความบกพร่องของแขนหลังโรคหลอดเลือดสมอง 60 คน กลุ่มละ 30 เป็นเวลาสี่สัปดาห์",
        result="บทความรายงานการดีขึ้นที่มากกว่าของการบำบัดด้วยกระจกแบบใหม่ใน FMA-UE, FMA-WH และดัชนี Barthel ฉบับปรับ นี่เป็นคำบรรยายระหว่างกลุ่มของการศึกษา ค่าเฉลี่ยและค่า P ไม่ได้คำนวณใหม่ในหน้านี้ ระหว่างที่หน้าวารสารยังถูกตรวจ ตัวเลขเหล่านั้นอยู่กับบทความ",
        sig=[
            "คำถามคือการเพิ่มการเคลื่อนไหวที่ช่วยซึ่งตรงกับกระจก เปลี่ยนคะแนนเทียบกับกระจกอย่างเดียวหรือไม่ หกสิบคนให้ความต่างขั้นต้น ไม่ใช่หลักฐานของโปรแกรมที่บ้าน",
            "การโยงภาพวารสารกับ SY-HR08E ช่วยให้ผู้อ่านจำอุปกรณ์ได้เท่านั้น ความต่างของคะแนนคงที่หรือไม่ รอการตรวจอิสระของตัวเลขเต็ม",
        ],
        limit="กลุ่มละ 30 คน ความต่างเป็นไปตามบทความ ค่าเฉลี่ยและค่า P ไม่ได้คำนวณใหม่ที่นี่ การโยงรุ่นเป็นการตรวจระหว่างรูปวารสารกับเอกสารทางการ")

    add(9, "th",
        title="อัมพาตครึ่งซีกซ้ายหลังกล้ามเนื้อสมองตาย MCA: บันทึกหนึ่งเรื่องของการกระตุ้นฟาราดิกร่วมมือหุ่นยนต์",
        desc="รายงานใน IJPRCP ชาย 60 ปีที่มีอัมพาตครึ่งซีกซ้ายเริ่มการกระตุ้นฟาราดิกกับ Syrebo C12 ประมาณสามเดือนหลังโรคหลอดเลือดสมอง ห้าครั้งต่อสัปดาห์ สี่สัปดาห์ รายที่รวมสองอย่างไม่โยงให้ส่วนใดส่วนหนึ่ง",
        lead="มือที่อัมพาตครึ่งซีกบางครั้งได้สองอย่างพร้อมกัน การกระตุ้นไฟฟ้าที่มุ่งกล้ามเนื้อ และมือหุ่นยนต์เพื่อแบและกำนิ้ว รายงานปี 2025 ใน International Journal of Physiotherapy Research and Clinical Practice บันทึกสี่สัปดาห์ของการกระตุ้นฟาราดิกกับ Syrebo C12 ในชายที่มีอัมพาตครึ่งซีกซ้าย นี่เป็นบันทึกแผนที่รวมกัน ไม่ใช่การศึกษาประสิทธิผลของชิ้นใดชิ้นหนึ่ง",
        bg=[
            "หลายเดือนหลังโรคหลอดเลือดสมอง การเปลี่ยนแปลงของมือมักช้าลง และแพทย์บางครั้งเพิ่มการกระตุ้นหรือความช่วยจากภายนอกเข้ากับการฝึกปกติ เมื่อใช้ทั้งสอง การเปลี่ยนก่อน-หลังมอบให้ข้างใดข้างหนึ่งอย่างสะอาดไม่ได้",
            "รายงานยังมีประโยชน์ บอกว่าแผนเริ่มเมื่อใด ทำบ่อยเพียงใด และอุปกรณ์ใดอยู่ในห้อง ไม่ให้ร้อยละ และไม่ให้ความต่างเทียบกลุ่มควบคุม",
        ],
        device="อุปกรณ์หุ่นยนต์ในรายงานคือ Syrebo C12 ภาพเป็นการตัดจากหน้าผลิตภัณฑ์ทางการของ C12 เพื่อให้จำเครื่องควบคุมและถุงมือได้ ไม่ได้เพิ่มสเปกที่บทความละไว้",
        design="การแทรกแซงรวมรายเดียว: การกระตุ้นฟาราดิกพร้อมการฝึกมือหุ่นยนต์ Syrebo C12 ไม่มีกลุ่มควบคุมขนาน",
        sample="ชาย 60 ปีที่มีอัมพาตครึ่งซีกซ้าย แผนเริ่ม 3 เดือน 2 สัปดาห์หลังโรคหลอดเลือดสมอง ห้าครั้งต่อสัปดาห์ เป็นเวลาสี่สัปดาห์",
        result="หน้านี้ไม่พิมพ์ซ้ำคะแนนการทำงานที่ยังไม่ได้ตรวจกับบทความสำหรับคอลัมน์ สิ่งที่ชัดคือการจัดวาง การกระตุ้นและการฝึกหุ่นยนต์ถูกใช้ร่วมกัน ดังนั้นการเปลี่ยนแปลงเขียนเป็นผลของ C12 อย่างเดียวหรือการกระตุ้นอย่างเดียวไม่ได้",
        sig=[
            "บันทึกเพิ่มตารางที่ชัดเจน ประมาณสามเดือนหลังโรคหลอดเลือดสมอง ห้าเซสชันต่อสัปดาห์ สองวิธีร่วมกัน ไม่ได้ยกระดับหลักฐาน",
            "รายอัมพาตครึ่งซีกซ้ายหลังกล้ามเนื้อสมองตาย MCA รายหนึ่ง ไม่แทนรอยโรคอื่นหรือเวลาอื่นหลังเริ่มเป็น",
        ],
        limit="รายรวมเดียว การเปลี่ยนแปลงไม่ถูกโยงให้ C12 หรือการกระตุ้น และไม่ใช่ผลทั่วไป")

    add(10, "th",
        title="อุปกรณ์ดามข้อมือ-มือแบบนิ่ม: การออกแบบและการประเมินเบื้องต้นใน Wearable Technologies",
        desc="Ledoux และ Barth รายงานอุปกรณ์ดามข้อมือ-มือพิมพ์สามมิติของตนเองใน Wearable Technologies บันทึกนี้อยู่กับบทความออกแบบนั้น ไม่จัดอันดับผลิตภัณฑ์เชิงพาณิชย์ และไม่ใช่การศึกษาประสิทธิผล",
        lead="ปี 2024 Wearable Technologies ของ Cambridge University Press เผยแพร่บทความออกแบบของ Ledoux และ Barth จากมหาวิทยาลัย Vanderbilt อุปกรณ์ที่พวกเขาสร้างและประเมินเบื้องต้นคืออุปกรณ์ดามการกำข้อมือ-มือพิมพ์สามมิติของพวกเขาเอง บทความกล่าวถึงโครงสร้างแบบนิ่มเชิงพาณิชย์ขณะพูดถึงมือที่สวมใส่ได้ คอลัมน์นี้ไม่เปลี่ยนการสนทนานั้นเป็นการจัดอันดับ และไม่ถือบทความเป็นหลักฐานประสิทธิผลของ Syrebo",
        bg=[
            "อุปกรณ์มือที่ออกจากห้องบำบัดต้องตอบเรื่องน้ำหนัก รูปทรง และคนสวมเองได้หรือไม่ บทความออกแบบมักบอกข้อจำกัดเหล่านั้นแล้วอธิบายต้นแบบ ไม่ได้รายงานการทดสอบการทำงานหลายศูนย์ก่อน การอ่านบทความออกแบบเหมือนบทความประสิทธิผลคือการสร้างผลลัพธ์ทางคลินิกที่ไม่ได้วัด",
            "โครงสร้างแบบนิ่มกับโครงกระดูกภายนอกแบบแข็งตอบปัญหาวิศวกรรมคนละอย่าง ความนิ่มเป็นทางหนึ่งในการลดรูปทรง การพูดถึงการเปลี่ยนแปลงการทำงานยังต้องการการศึกษาในคนของมันเอง",
        ],
        device="ข้อความตอนต้นคือหน้าแรกแบบเปิดเสรี (CC BY 4.0) ไม่ใช่ตารางเปรียบเทียบ ภาพผลิตภัณฑ์แสดงระบบถุงมือคลินิก Syrebo ไม่ใช่รูปจากการทดลองนี้",
        design="การออกแบบ การจำลอง และการประเมินเบื้องต้นของอุปกรณ์ดามพิมพ์สามมิติของผู้เขียนเอง บทความไม่ใช่การศึกษาแบบสุ่มของ Syrebo และไม่ใช่การเปรียบเทียบประสิทธิผลระหว่างอุปกรณ์ที่วางตลาด",
        sample="ส่วนที่มีคนเป็นการมองเบื้องต้นที่ต้นแบบของผู้เขียน ขนาดและงานเป็นของบทความ ไม่ได้เขียนใหม่ที่นี่เป็นกลุ่มประชากร Syrebo",
        result="หน้านี้ไม่อ้างคำคุณศัพท์เชิงพาณิชย์ และไม่เรียงยี่ห้ออื่น สิ่งที่เหลือคือบทความเป็นการศึกษาออกแบบแบบเปิดเสรีเรื่องโครงสร้างที่นิ่มและสวมใส่ได้ คำว่า presumably ของผู้เขียนชี้ว่าความสบายเป็นสิ่งที่พวกเขาไม่ได้ถือเป็นผลลัพธ์ที่วัดแล้ว",
        sig=[
            "บทความอยู่ในคอลัมน์เพื่อให้การศึกษาออกแบบแยกจากการศึกษาประสิทธิผล โครงสร้างแบบนิ่มทำให้อุปกรณ์สวมในชีวิตประจำวันง่ายขึ้นหรือไม่ เป็นการศึกษาการสวมกับการศึกษาการทำงาน แยกกัน",
            "การเปิดเสรีให้ผู้อ่านตรวจถ้อยคำได้ จุดประสงค์ของการตรวจคือไม่ให้ข้อสันนิษฐานกลายเป็นข้อสรุป ไม่ใช่เพื่อเลือกผลิตภัณฑ์ที่เบาที่สุด",
        ],
        limit="ไม่ใช่การศึกษาประสิทธิผลของ Syrebo และไม่ใช่การจัดอันดับผลิตภัณฑ์ แหล่งข้อมูลกันความสบายด้วยคำว่า presumably การตัดหน้าแรกไม่มีตารางเปรียบเทียบ")

    add(11, "th",
        title="หุ่นยนต์นิ้วที่มุ่งใช้ที่บ้าน: บันทึกการพัฒนาใน Journal of the Robotics Society of Japan",
        desc="บทความปี 2023 ใน Journal of the Robotics Society of Japan พูดถึงหุ่นยนต์นิ้วสำหรับใช้ที่บ้านในอัมพาตครึ่งซีก และระบุ Syrebo ในตัวอย่างที่ทำให้เป็นผลิตภัณฑ์ได้ไม่กี่ราย ไม่ใช่การทดลองทางคลินิก",
        lead="การฟื้นฟูมือที่บ้านถูกพูดถึงมาหลายปี ตัวอย่างที่ทำให้เป็นผลิตภัณฑ์ในวรรณกรรมของสมาคมยังมีน้อย ปี 2023 Journal of the Robotics Society of Japan เผยแพร่บทความของ Furudate และคณะ เรื่องหุ่นยนต์ฟื้นฟูนิ้วที่มุ่งใช้ที่บ้านหลังอัมพาตครึ่งซีก และการพัฒนาร่วมกับแพทย์ ผู้เขียนบันทึกว่ากรณีใช้ที่บ้านที่ทำให้เป็นผลิตภัณฑ์แล้วยังหายาก และระบุถุงมือมือ Syrebo เป็นกรณีหนึ่ง บทความเป็นบันทึกการพัฒนาและความร่วมมือ ไม่ใช่การศึกษาประสิทธิผล",
        bg=[
            "ระหว่างหอผู้ป่วยกับบ้านมีการสวมใส่ ขีดจำกัดความปลอดภัย และการใช้เมื่อไม่มีนักบำบัดในห้อง บทความวิศวกรรมวางข้อจำกัดเหล่านั้นในงานร่วมกับแพทย์ การถูกเอ่ยชื่อหมายความว่าผู้เขียนเลือกผลิตภัณฑ์นี้เป็นตัวอย่าง ไม่ได้หมายความว่าสมาคมทำการศึกษาที่มีกลุ่มควบคุม",
            "«มีไม่กี่รายที่ทำให้เป็นผลิตภัณฑ์» ก็เป็นขีดจำกัดเช่นกัน การอ่านว่า «การฟื้นฟูที่บ้านมีใช้ทั่วไปแล้ว» เปลี่ยนตัวอย่างให้เป็นข้ออ้างทางระบาดวิทยา",
        ],
        device="บทความไม่ได้พิมพ์ภาพถุงมือ ภาพถุงมือและเครื่องควบคุมในคอลัมน์นี้คือรูปที่ 2 ของรายงาน Cureus ปี 2024 โดย Sharma และคณะ (CC BY 4.0) คำบรรยายบอกไว้ ไม่ใช่รูปต้นฉบับของบทความสมาคมญี่ปุ่น",
        design="บทความพัฒนาในวารสารสมาคม เรื่องหุ่นยนต์นิ้วสำหรับใช้ที่บ้านและเรื่องการทำงานกับแพทย์ ไม่มีการสุ่ม และไม่มีการเปรียบเทียบการทำงานระหว่างกลุ่ม",
        sample="ขนาดกลุ่มตัวอย่างทางคลินิกไม่ใช้ บทความพูดถึงทางไปสู่ผลิตภัณฑ์ ไม่ใช่ผลในกลุ่มคน",
        result="ข้อความที่ใช้ที่นี่คือ หุ่นยนต์นิ้วที่ทำให้เป็นผลิตภัณฑ์และมุ่งที่บ้านยังมีน้อย และ Syrebo เป็นตัวอย่างหนึ่งที่ผู้เขียนระบุ คอลัมน์รักษาขอบเขตนั้น ไม่ได้เขียนใหม่เป็นประสิทธิผล อันดับตลาด หรือคำสัญญาว่าการฝึกที่บ้านจะทำจนจบ",
        sig=[
            "คุณค่าของบันทึกคือการใช้ที่บ้านถูกถือเป็นปัญหาวิศวกรรมที่กำหนดร่วมกับแพทย์ ตัวอย่างที่ทำให้เป็นผลิตภัณฑ์แล้วแสดงว่าอุปกรณ์หนึ่งเดินจากต้นแบบไปเป็นผลิตภัณฑ์",
            "จะใช้ที่บ้านอย่างปลอดภัยและซ้ำได้หรือไม่ ยังขึ้นกับข้อบ่งใช้ การกำกับ และการศึกษาทางคลินิกแยกต่างหาก บทความของสมาคมไม่ได้ให้ข้อมูลเหล่านั้น",
        ],
        limit="ไม่ใช่การทดลองทางคลินิกของ Syrebo แหล่งข้อมูลเน้นว่าตัวอย่างที่ทำให้เป็นผลิตภัณฑ์ยังมีน้อย ภาพมาจากรายงานผู้ป่วยเปิดเสรีอีกเรื่อง")

