    add(1, "hi",
        title="तीव्र स्ट्रोक में हाथ का कार्य: NP Brain अस्पताल में रोबोट-सहायता प्रशिक्षण का यादृच्छिक अध्ययन",
        desc="NP Brain अस्पताल में 30 रोगियों का यादृच्छिक अध्ययन: रोबोट-सहायता हाथ प्रशिक्षण न्यूरोडेवलपमेंटल थेरेपी में जोड़ा गया। Nine-Hole Peg, ABILHAND और Barthel निष्कर्ष अध्ययन के परिणाम हैं।",
        lead="स्ट्रोक के बाद हाथ अक्सर चलने की तुलना में दैनिक कामों में धीरे लौटता है: प्याला, बटन या चम्मच एक ठोस बाधा बन जाता है। तीव्र खिड़की तेज़ी से बदलती है, इसलिए उसमें जो जोड़ा जाए उसे एक मामले की छाप से नहीं, यादृच्छिक तुलना से मापना होता है। 2026 में Scientific Reports ने तुर्की के NP Brain अस्पताल का यादृच्छिक अध्ययन छापा, जिसमें सामान्य न्यूरोडेवलपमेंटल थेरेपी में Syrebo रोबोट-सहायता हाथ प्रशिक्षण जोड़ा गया। लेख बताता है कि केवल थेरेपी की तुलना में निपुणता, दोनों हाथों के काम और आत्म-देखभाल में अधिक लाभ हुआ। नमूना 30 लोगों का है, और स्पास्टिसिटी ने समूहों को अलग नहीं किया।",
        bg=[
            "हाथ कठिन है क्योंकि उसे बल, अलग-अलग गति और वास्तविक उपयोग चाहिए। चाल को एक लक्ष्य की तरह अभ्यास किया जा सकता है; हाथ को अस्थिर मुद्रा के भीतर पकड़ना और छोड़ना पड़ता है। न्यूरोडेवलपमेंटल थेरेपी पहले से तीव्र पुनर्वास का आधार है, पर चिकित्सक हर पकड़ को अनंत बार दोहरा नहीं सकता, इसलिए खुराक और निरंतरता बढ़ाना कठिन है।",
            "नरम रोबोटिक दस्ताना सिद्धांत रूप में वे दोहराव निगरानी में दे सकता है। तीव्र रोगी अभी बदल रहे होते हैं। उपकरण सुरक्षित जोड़ा जा सकता है या नहीं, और कार्यात्मक अंक उसके साथ हिलते हैं या नहीं, नियंत्रित प्रश्न है। यह अध्ययन उस चरण को देखता है, किसी दीर्घकालिक अध्ययन की पुनरावृत्ति नहीं।",
        ],
        device="लेख उपकरण को SYREBO रोबोटिक हाथ कहता है। फ़ोटो नरम दस्ताना, कंसोल और टैबलेट दिखाती है ताकि पाठक रूप देख सके। मॉडल का विवरण लेख और नैदानिक प्रोटोकॉल का है।",
        design="एकल केंद्र की यादृच्छिक तुलना। एक समूह को रोबोट-सहायता हाथ प्रशिक्षण और न्यूरोडेवलपमेंटल थेरेपी (NT) मिली। नियंत्रण समूह को केवल NT मिली। परिणाम सूक्ष्म निपुणता, दोनों हाथों के दैनिक काम और आत्म-देखभाल थे, केवल बल नहीं।",
        sample="NP Brain अस्पताल ने तीव्र चरण के 30 लोगों को लिया और यादृच्छिक किया। सहायता सत्र सप्ताह में तीन बार, आठ सप्ताह तक रहे। स्पास्टिसिटी के माप भी लिए गए।",
        result="लेख रोबोट-सहायता समूह में Nine-Hole Peg Test, ABILHAND प्रश्नावली और Barthel सूचकांक पर अधिक सुधार बताता है। यह इस नमूने में समूहों के बीच का निष्कर्ष है। यह वादा किया गया सुधार-वेग नहीं है। स्पास्टिसिटी पर सार्थक अंतर-समूह अंतर नहीं दिखा, इसलिए हर माप अलग नहीं हुआ।",
        sig=[
            "उपयोगी हिस्सा समय है: सहायता अभ्यास को दीर्घकालिक परिणामों से नहीं लिया गया, बल्कि चल रही न्यूरोडेवलपमेंटल थेरेपी के सामने तीव्र चरण में परखा गया। तीन कार्यात्मक मापों का साथ हिलना एक अंक से अधिक बताता है।",
            "तीस यादृच्छिक रोगी केवल सावधानीपूर्ण पढ़ने को संभालते हैं। अध्ययन दीर्घ घरेलू उपयोग का उत्तर नहीं देता, और यह नहीं दिखाता कि हर स्ट्रोक उप-प्रकार वही रास्ता लेता है। योजना अब भी उपचार करने वाला चिकित्सक तय करता है।",
        ],
        limit="छोटा नमूना (n=30)। स्पास्टिसिटी पर सार्थक अंतर-समूह अंतर नहीं। अंकों का बदलाव अध्ययन की रिपोर्ट है, व्यक्तिगत वादा नहीं।")

    add(2, "hi",
        title="स्ट्रोक के बाद हाथ का कार्य: नरम रोबोटिक दस्ताने और मिरर थेरेपी का एकल-अंध RCT, 6 महीने के अनुवर्तन के साथ",
        desc="Journal of Rehabilitation Medicine, 2025: 49 प्रतिभागी, नरम रोबोटिक दस्ताना बनाम मिरर थेरेपी, आठ सप्ताह और छह महीने का अनुवर्तन। अंतर-समूह P मान लेख की रिपोर्ट हैं।",
        lead="मिरर थेरेपी दृश्य इनपुट से प्रभावित पक्ष को बुलाती है। नरम रोबोटिक दस्ताना लचीले चालक से खोलना और बंद करना दोहराता है। कौन सा बदलाव अधिक देर रहता है, यह अंतिम प्रशिक्षण दिन पर नहीं कहा जा सकता। Journal of Rehabilitation Medicine में 2025 का एकल-अंध यादृच्छिक अध्ययन दोनों तरीकों की आठ सप्ताह तुलना करता है और लोगों को छह महीने तक देखता है। लेख प्रशिक्षण के अंत में Box and Block Test, ग्रिप शक्ति और FMA-UE पर दस्ताने के पक्ष में सांख्यिकीय रूप से सार्थक अंतर-समूह लाभ बताता है, और बताता है कि दस्ताना समूह के वे लाभ छह महीने पर भी थे।",
        bg=[
            "हाथ प्रशिक्षण के बाद जो प्रश्न मायने रखता है वह यह है कि घर लौटने पर बदलाव अभी है या नहीं। मिरर थेरेपी सरल है और प्रतिबिंबित अंग पर ध्यान पर निर्भर करती है। दस्ताना दोहराव को बाहरी चालक पर ले जाता है, ध्यान और सहनशक्ति की माँग अलग होती है। दोनों पुनर्वास विधियाँ हैं। यह ब्रांडों की रैंकिंग नहीं है।",
            "अंतिम प्रशिक्षण दिन का अंक छोटे उद्दीपन को स्थिर बदलाव समझ सकता है। छह महीने की मुलाकात वाली यादृच्छिक तुलना वह भेद संभव करती है।",
        ],
        device="कॉलम की फ़ोटो E12 मिरर-प्रशिक्षण व्यवस्था दिखाती है। अध्ययन का उपकरण वही है जो लेख बताता है; फ़ोटो मॉडल का मेल नहीं है।",
        design="नरम रोबोटिक दस्ताने की मिरर थेरेपी के विरुद्ध एकल-अंध यादृच्छिकीकरण। परिणाम पकड़ने-छोड़ने की निपुणता (Box and Block), ग्रिप शक्ति और ऊपरी अंग की गति (FMA-UE) थे, प्रशिक्षण के छह महीने बाद मुलाकात के साथ।",
        sample="स्ट्रोक के बाद उनचास लोगों को यादृच्छिक किया गया। प्रशिक्षण आठ सप्ताह चला। रजिस्ट्री NCT05898971 है।",
        result="प्रशिक्षण के अंत में लेख दस्ताने के पक्ष में अंतर-समूह अंतर बताता है: Box and Block P=0.004, ग्रिप P=0.011, FMA-UE P=0.021। छह महीने पर दस्ताना समूह के लाभ अभी थे। वे P मान इस नमूने का वर्णन करते हैं। वे हर रोगी को सुधार का आकार नहीं देते।",
        sig=[
            "अतिरिक्त जानकारी समय है। अंतर-समूह अंतर अनुवर्तन मुलाकात पर गायब नहीं हुआ था। यह अंतिम प्रशिक्षण दिन की रैंकिंग से चिकित्सकीय रूप से अधिक उपयोगी है।",
            "उनचास लोग अभी भी छोटा अध्ययन है। आधार अंतर, घाव का पक्ष और छुट्टी के बाद का अभ्यास छह महीने का अंक हिला सकते हैं। निष्कर्ष इस जनसंख्या और इस तुलना का है।",
        ],
        limit="छोटा नमूना (n=49)। P मान और बने रहे लाभ अध्ययन की रिपोर्ट हैं, उत्पाद का वादा नहीं।")

    add(3, "hi",
        title="उप-तीव्र स्ट्रोक में एकपक्षीय नेग्लेक्ट: SY-HRE12 पर रोबोटिक मिरर प्रशिक्षण की यादृच्छिक तुलना",
        desc="NeuroRehabilitation, 2025: उप-तीव्र चरण के 24 लोग, सब SY-HRE12 पर। मिरर मोड बनाम पूर्व-निर्धारित निष्क्रिय गति, 30 मिनट, सप्ताह में तीन बार, पाँच सप्ताह।",
        lead="उप-तीव्र चरण के कुछ लोगों के पास केवल कमज़ोर हाथ नहीं होता। वे स्थान के एक पक्ष की उपेक्षा भी कर सकते हैं, और मनोदशा भी प्रभावित हो सकती है। रोबोटिक मिरर प्रशिक्षण कम प्रभावित हाथ को प्रभावित हाथ पर रखता है, ताकि दृष्टि और गति एक ही दोहराव में आएँ। NeuroRehabilitation में 2025 के यादृच्छिक अध्ययन ने एक ही नरम दस्ताने के दो उपयोगों की तुलना की: उसकी मिरर क्रिया और पूर्व-निर्धारित निष्क्रिय मोड। लेख नेग्लेक्ट और अवसाद से जुड़े परिणामों पर मिरर प्रशिक्षण का लाभ बताता है। नमूना 24 लोगों का है।",
        bg=[
            "नेग्लेक्ट अंकों को पढ़ना कठिन बनाता है। समस्या केवल यह नहीं कि हाथ नहीं उठता; स्थान के एक पक्ष पर ध्यान कम है। साधारण दर्पण यह आभास दे सकता है कि प्रभावित हाथ हिल रहा है, जबकि वह नहीं हिल रहा। रोबोटिक मिरर प्रभावित दस्ताने को दूसरे हाथ के साथ हिलाने की कोशिश करता है, ताकि देखना और करना एक ही प्रयास में हों।",
            "यदि समूह अलग उपकरण इस्तेमाल करते, तो कोई भी अंतर हार्डवेयर हो सकता था। इस अध्ययन ने दोनों समूहों को SY-HRE12 दिया और केवल मोड बदला। प्रश्न यह है कि दस्ताना कैसे चलाया गया, यह नहीं कि नई मशीन थी या नहीं।",
        ],
        device="लेख ने SYREBO SY-HRE12 का उपयोग किया। फ़ोटो E12 कंसोल, चालित दस्ताना और मिरर दस्ताना दिखाती है ताकि प्रणाली पहचानी जा सके। अध्ययन का उपकरण SY-HRE12 है।",
        design="यादृच्छिक तुलना। दोनों समूहों ने SY-HRE12 का उपयोग किया। एक समूह ने मिरर क्रिया का उपयोग किया। दूसरे ने पूर्व-निर्धारित निष्क्रिय गति का। परिणामों में एकपक्षीय नेग्लेक्ट, अवसाद से जुड़े माप और दैनिक गतिविधियाँ थीं।",
        sample="उप-तीव्र चरण के चौबीस लोग, प्रत्येक समूह में 12। सत्र 30 मिनट के, सप्ताह में तीन बार, पाँच सप्ताह तक।",
        result="इस नमूने में लेख नेग्लेक्ट और अवसाद से जुड़े परिणामों पर पूर्व-निर्धारित निष्क्रिय गति की तुलना में रोबोटिक मिरर प्रशिक्षण का लाभ बताता है। यह एक उपकरण के दो मोड के बीच का अंतर है। इसका अर्थ यह नहीं कि दस्ताना नेग्लेक्ट या अवसाद का उपचार करता है। नियंत्रण स्थिति साधारण मिरर बॉक्स नहीं थी।",
        sig=[
            "प्रश्न «दस्ताना उपयोग करें या नहीं» से «उसी दस्ताने का कौन सा मोड» की ओर खिसकता है। जिन लोगों में नेग्लेक्ट और मनोदशा का भार भी है, उनके लिए यह अधिक सटीक नैदानिक प्रश्न है।",
            "चौबीस प्रतिभागी केवल सावधानीपूर्ण पढ़ने को संभालते हैं। अध्ययन बिना निगरानी घरेलू उपयोग की जाँच नहीं करता, और ध्यान या मनोदशा में गारंटीशुदा बदलाव नहीं देता।",
        ],
        limit="छोटा नमूना (प्रति समूह 12)। नियंत्रण मोड पूर्व-निर्धारित निष्क्रिय गति था, मिरर बॉक्स नहीं। अंतर अध्ययन की रिपोर्ट हैं।")

    add(4, "hi",
        title="स्ट्रोक के बाद ग्रिप और मोटर अंक: रोबोटिक प्रशिक्षण दस्तानों का यादृच्छिक अध्ययन",
        desc="SPORT TK, 2025: 30 प्रतिभागी। बताए गए माध्य अंतर: ग्रिप 1.87 (95% CI 0.39–3.35, P=0.015) और Fugl-Meyer 16.67 (95% CI 3.9–29.4, P=0.012)। कोई मॉडल नहीं बताया गया।",
        lead="स्ट्रोक के बाद चिकित्सक हाथ को अक्सर दो व्यावहारिक प्रश्नों में बाँटते हैं: क्या वह पकड़ सकता है, और क्या वह नियंत्रण से हिल सकता है। SPORT TK-EuroAmerican Journal of Sport Sciences में 2025 के यादृच्छिक अध्ययन ने दोनों मापे। लेख रोबोटिक प्रशिक्षण दस्तानों के पक्ष में ग्रिप और Fugl-Meyer मोटर अंक पर सांख्यिकीय रूप से सार्थक अंतर-समूह माध्य अंतर बताता है। तीस लोग शामिल हुए, और लेख कोई व्यावसायिक मॉडल नहीं बताता।",
        bg=[
            "ग्रिप का बदलाव उपयोगी गति ज़रूरी नहीं देता, और ऊँचा मोटर अंक यह नहीं कहता कि व्यक्ति प्याला उठा सकता है। बल और गति को एक ही यादृच्छिक तुलना में मापना दोनों में से केवल अच्छे दिखने वाले को छापने से बचाता है।",
            "दस्ताना लेख अक्सर मॉडल छोड़ देते हैं। मॉडल के बिना परिणाम को उत्पाद विनिर्देश पर नहीं उतारा जा सकता। यह सार इसलिए उन्हीं अंतरों पर रहता है जो लेख वास्तव में देता है।",
        ],
        device="",
        design="रोबोटिक प्रशिक्षण-दस्ताना अभ्यास की नियंत्रण स्थिति से यादृच्छिक तुलना। साझा परिणाम ग्रिप और Fugl-Meyer मोटर अंक थे, 95% विश्वास अंतराल के साथ माध्य अंतर के रूप में।",
        sample="स्ट्रोक के बाद तीस लोग, प्रत्येक समूह में 15। लेख कोई बाज़ार मॉडल नहीं पहचानता। सामान्य दस्ताना फ़ोटो चित्रण है, उपकरण की पहचान नहीं।",
        result="बताए गए अंतर-समूह माध्य अंतर हैं ग्रिप 1.87 (95% CI 0.39 से 3.35, P=0.015) और Fugl-Meyer 16.67 (95% CI 3.9 से 29.4, P=0.012)। माध्य अंतर हर व्यक्ति का लाभ नहीं है। मोटर अंक का अंतराल चौड़ा है, जो छोटे नमूने का रूप है जब अनुमान सटीक नहीं।",
        sig=[
            "अंतर और अंतराल दोनों छापना «नियंत्रण से बेहतर» वाक्य से अधिक उपयोगी है। दिशा दिखती है, अनिश्चितता भी।",
            "क्योंकि कोई मॉडल नहीं बताया गया, परिणाम को किसी विशेष Syrebo दस्ताने की विशिष्टता या संकेत के रूप में नहीं कहा जा सकता। तीस लोग नमूना-शोर के लिए भी जगह छोड़ते हैं।",
        ],
        limit="छोटा नमूना (n=30)। कोई मॉडल नहीं पहचाना गया, और फ़ोटो मेल नहीं है। माध्य अंतर और P मान अध्ययन के आँकड़े हैं।")

    add(5, "hi",
        title="प्रारंभिक उप-तीव्र हाथ कार्य: हुआशान टीम का SY-HR03E एकल-अंध पायलट RCT",
        desc="BioMedical Engineering OnLine में एकल-अंध पायलट RCT: 20 भर्ती रोगी, SY-HR03E, चार सप्ताह। लेख पूर्ण समाप्ति, कोई प्रतिकूल घटना नहीं, और हाथ अंकों व दैनिक गतिविधियों पर प्रारंभिक संकेत बताता है।",
        lead="प्रारंभिक उप-तीव्र चरण में पहला प्रश्न यह नहीं कि अंक कितने बढ़ सकते हैं। प्रश्न यह है कि सत्र पूरे हो सकते हैं या नहीं, और वे सुरक्षित हैं या नहीं। फुदान विश्वविद्यालय के हुआशान अस्पताल में प्रोफ़ेसर Jia Jie के नेतृत्व वाली टीम ने उस खिड़की में हाथ पुनर्वास के लिए Syrebo SY-HR03E पर BioMedical Engineering OnLine में एकल-अंध पायलट यादृच्छिक अध्ययन छापा। लेख बताता है कि सभी 20 प्रतिभागियों ने चार सप्ताह पूरे किए, बिना छूटे और बिना प्रतिकूल घटना के। हाथ के अंक दोनों समूहों में सुधरे, दस्ताना समूह में बदलाव बड़ा था। दैनिक गतिविधियों में समूह-के-भीतर बदलाव दस्ताना समूह में सांख्यिकीय सार्थकता तक पहुँचा।",
        bg=[
            "बाँह और हाथ आमतौर पर चलने से देर से ठीक होते हैं। खाना, कपड़े पहनना और धोना उँगलियों की अलग गति पर निर्भर करते हैं, एक बल-संख्या पर नहीं। सामान्य हाथ थेरेपी मदद करती है, पर चिकित्सक जितने दोहराव दे सकता है वे सीमित हैं, और वही गति बिस्तर के पास दोहराना कठिन है।",
            "वायवीय दस्ताना उँगलियों को हाथ पर कम द्रव्यमान के साथ मोड़ और फैला सकता है, इसलिए बिस्तर-किनारे उपयोग की बात होती है। प्रारंभिक उप-तीव्र चरण के लोग स्वतः भी ठीक होते हैं। किसी भी «प्रारंभिक प्रभाव» को उस पृष्ठभूमि पर पढ़ना होता है। पायलट यादृच्छिक अध्ययन यह दिखाने के लिए है कि प्रोटोकॉल संभव है, और बड़े अध्ययन के लिए संकेत छोड़ने के लिए। यह पुष्टिकारक अध्ययन की जगह नहीं लेता।",
        ],
        device="लेख SY-HR03E को व्यावसायिक नरम दस्ताना और टेबलटॉप नियंत्रक बताता है। बताया गया द्रव्यमान प्रणाली के लिए लगभग 3.5 किग्रा और दस्ताने के लिए लगभग 110 ग्राम है। हाथ की पीठ पर वायवीय बैलोज़ मोड़ने और फैलाने में सहायता करते हैं। दाब संवेदक उस बदलाव को देखते हैं जब व्यक्ति हिलने की कोशिश करता है; 0.7 kPa की पूर्व-निर्धारित सीमा के ऊपर नियंत्रक उस बदलाव को गति-इरादा मानता है और फुलाता या पिचकाता है। इच्छित मोड सक्रिय सहायता है, पूरी तरह निष्क्रिय खिंचाव नहीं।",
        design="एकल-अंध पायलट यादृच्छिकीकरण। रोबोटिक समूह ने मानक पुनर्वास में दस्ताना-सहायता खोलना-बंद करना जोड़ा। सामान्य समूह को उसी सत्र-लंबाई की पारंपरिक हाथ थेरेपी मिली। दोनों समूहों को प्रतिदिन एक घंटा मानक पुनर्वास भी मिला। चिकित्सक ने मुद्रा की निगरानी की। रजिस्ट्री: ChiCTR2000034614।",
        sample="बीस भर्ती रोगी, शुरुआत के 7 दिन से 3 महीने तक, प्रत्येक समूह में 10। दस्ताना सत्र प्रतिदिन 30 मिनट, सप्ताह में पाँच दिन, चार सप्ताह। हर खोलना-बंद करना लगभग तीन सेकंड रोका गया। लेखक संबद्धताओं में नैदानिक टीम है और, जैसा लेख बताता है, Shanghai Siyi Intelligent Technology। वह संबंध पढ़ने का हिस्सा है।",
        result="लेख बताता है कि सभी 20 लोगों ने चार सप्ताह पूरे किए, बिना छूटे और बिना प्रतिकूल घटना के। हाथ के Fugl-Meyer अंक दोनों समूहों में सुधरे, रोबोटिक समूह में सुधार बड़ा था। संशोधित Barthel सूचकांक पर केवल रोबोटिक समूह का समूह-के-भीतर बदलाव सांख्यिकीय रूप से सार्थक बताया गया है (p<0.001); सामान्य समूह का समूह-के-भीतर बदलाव नहीं। हाथ की Brunnstrom अवस्था ने भी सार्थक समूह-के-भीतर बदलाव केवल रोबोटिक समूह में दिखाया। 10 बनाम 10 पायलट में समूह-के-भीतर P मान संकेत है, यह प्रमाण नहीं कि दैनिक कार्य रोगियों में सामान्य रूप से बढ़ेगा।",
        sig=[
            "कई नरम-दस्ताना अध्ययन दीर्घकालिक चरण के लोगों को लेते हैं। यह पायलट संभावना और सुरक्षा का प्रश्न 7 दिन से 3 महीने की खिड़की में ले जाता है। यह दीर्घकालिक प्रभावशीलता के दावों को आगे नहीं खिसकाता।",
            "हाथ के अंक और दैनिक-गतिविधि अंक एक ही सांख्यिकीय रूप में नहीं आए: लेख सार्थक समूह-के-भीतर Barthel बदलाव केवल दस्ताना समूह में बताता है। वह विभाजन फिर से जाँचने योग्य है। यह कथन नहीं कि दैनिक जीवन की गतिविधियाँ हल हो गईं। 110 ग्राम का दस्ताना और इरादा-पहचान बिस्तर-किनारे और बाद में घर की चर्चा संभव करते हैं। यह अध्ययन स्वयं भर्ती रोगियों में हुआ।",
        ],
        limit="पायलट यादृच्छिकीकरण, प्रति समूह 10। प्रारंभिक संकेतों को बड़े नमूने की ज़रूरत है। P मान उस परिणाम के लिए लेख की रिपोर्ट है। उपकरण-संबंधी संबद्धता बताई गई है और उसे तौलना चाहिए।")

    add(6, "hi",
        title="कफ-रुकावट पैटर्न में हाथ की हानि: दस्ताना और विद्युत-एक्यूपंक्चर का 200 लोगों का चार-भुजा अध्ययन",
        desc="Journal of Hunan University of Chinese Medicine: 200 प्रतिभागी, चार भुजाएँ। बताई गई कुल प्रभावी दरें 88%, 76%, 77.6% और 70.8% थीं। ये आँकड़े अध्ययन का संयुक्त माप हैं, उत्पाद दर नहीं।",
        lead="रोबोटिक दस्ताना और विद्युत-एक्यूपंक्चर को एक योजना में रखना एक विशिष्ट एकीकृत विकल्प है, और परिणाम उस भुजा से जुड़ा रहना चाहिए जिसने उसे दिया। Journal of Hunan University of Chinese Medicine में 2022 के चार-भुजा अध्ययन ने phlegm-stasis blocking collaterals पैटर्न में स्ट्रोक के बाद हाथ की हानि वाले 200 लोगों को लिया और दस्ताना तथा विद्युत-एक्यूपंक्चर, केवल दस्ताना, केवल विद्युत-एक्यूपंक्चर और सामान्य पुनर्वास की तुलना की। लेख की अपनी «कुल प्रभावी दरें» 88%, 76%, 77.6% और 70.8% हैं। वह संयुक्त माप लेखकों का सार है। यह उत्पाद प्रभावशीलता दर नहीं है।",
        bg=[
            "इस पैटर्न निदान के अंतर्गत रास्ते अक्सर आधुनिक पुनर्वास को विद्युत-एक्यूपंक्चर से जोड़ते हैं। चार-भुजा विन्यास संयोजन, केवल उपकरण, केवल एक्यूपंक्चर और सामान्य देखभाल को एक पैमाने पर दिखा सकता है, बिना तुलना वाली पहले-बाद कहानी के बजाय।",
            "कुल प्रभावी दर कई निर्णयों को एक प्रतिशत में समेटती है। यह मोटे अंतर के लिए उपयोगी है और नामित पैमाने पर एक व्यक्ति के बदलाव के रूप में अनुपयोगी। इसे «दस्ताने की प्रभावशीलता 88% है» कहकर उद्धृत नहीं किया जा सकता।",
        ],
        device="",
        design="चार भुजाएँ: रोबोटिक दस्ताना और विद्युत-एक्यूपंक्चर, केवल दस्ताना, केवल विद्युत-एक्यूपंक्चर, और सामान्य पुनर्वास। यहाँ चर्चित परिणाम लेख की कुल प्रभावी दर है। संबद्धताओं में Shanghai Siyi Intelligent Technology है, सह-लेखक Yin Ganggang। वह प्रकटीकरण पढ़ने में रहता है।",
        sample="phlegm-stasis blocking collaterals पैटर्न में स्ट्रोक के बाद हाथ की हानि वाले दो सौ लोग। यह कॉलम का सबसे बड़ा नमूना है। लेख ऐसा मॉडल नहीं बताता जिसे वर्तमान उत्पाद से मिलाया जा सके, और सामान्य फ़ोटो ऐसा मेल नहीं है।",
        result="बताई गई कुल प्रभावी दरें हैं दस्ताना और विद्युत-एक्यूपंक्चर के लिए 88%, केवल दस्ताने के लिए 76%, केवल विद्युत-एक्यूपंक्चर के लिए 77.6%, और सामान्य पुनर्वास के लिए 70.8%। संयुक्त भुजा में ऊँचा संयुक्त माप केवल यह कहता है कि इस अध्ययन के नियम के अंतर्गत उस भुजा ने अधिक अंक पाए। यह 88% दस्ताने को नहीं देता, और 76% उत्पाद दर नहीं है। केवल दस्ताने और केवल विद्युत-एक्यूपंक्चर के आँकड़े पास हैं, जो पूरे पैटर्न को एक घटक से समझाने के विरुद्ध भी है।",
        sig=[
            "दो सौ लोग और चार भुजाएँ तुलना योग्य संयुक्त माप देते हैं, उत्पाद पृष्ठ के लिए प्रतिशत नहीं। कुल प्रभावी दर के रूप में पढ़ें तो संयोजन, एकल विधियों और सामान्य देखभाल के बीच अंतर सीमित हैं।",
            "लेख, जैसा यहाँ संक्षेपित है, कॉलम के अन्य अध्ययनों जैसे माध्य अंतर नहीं देता। जब तक वे पैमाने मेज़ पर नहीं, अध्ययन इस बारे में है कि घटक कैसे जोड़े गए, इस बारे में नहीं कि हाथ का अंक कितने बिंदु बढ़ेगा।",
        ],
        limit="प्रतिशत अध्ययन की अपनी कुल प्रभावी दरें हैं। संयुक्त भुजा को अकेले दस्ताने या अकेले विद्युत-एक्यूपंक्चर से नहीं जोड़ा जा सकता। कोई मॉडल नहीं बताया गया।")

    add(7, "hi",
        title="मध्य मस्तिष्क धमनी रोधगलन के बाद हाथ पुनर्वास: 66 वर्ष की एक रोगी का मामला",
        desc="Cureus मामला: द्विपक्षीय MCA क्षेत्र रोधगलन वाली 66 वर्ष की महिला को नैदानिक निगरानी में Syrebo दस्ताना कार्यक्रम मिला। एक मामला सामान्य परिणाम नहीं है।",
        lead="यादृच्छिक अध्ययन औसत अंतर बताता है। मामला बताता है कि एक व्यक्ति के लिए पुनर्वास कैसे रखा गया। 2024 में Cureus में Sharma और सहयोगियों ने मध्य मस्तिष्क धमनी क्षेत्रों में रोधगलन वाली 66 वर्ष की महिला की रिपोर्ट की, जिसे Syrebo दस्ताना कार्यक्रम के चारों ओर न्यूरोफिज़ियोथेरेपी मिली। रिपोर्ट अवलोकन और कार्यात्मक बदलाव का क्रम बताती है। यह एक मामला है, और सामान्य नहीं होता।",
        bg=[
            "इस क्षेत्र का रोधगलन अक्सर बाँह और हाथ को भाषा या संज्ञान के साथ प्रभावित करता है, इसलिए योजना कमज़ोर हाथ से बड़ी होती है। परिवारों को आमतौर पर प्रतिशत से अधिक यह जानना होता है कि दस्ताना अभ्यास फिज़ियोथेरेपी में कहाँ बैठा, और किसने निगरानी की।",
            "मामला वह क्रम लिख सकता है। समानांतर नियंत्रण नहीं है, इसलिए कोई भी पहले-बाद बदलाव स्वतः सुधार, सामान्य देखभाल और दस्ताने को मिलाता है। उन टुकड़ों को अलग नहीं किया जा सकता।",
        ],
        device="लेख Syrebo दस्ताना कार्यक्रम की चर्चा करता है और मॉडल नहीं बताता। दस्ताना और कंसोल की फ़ोटो उस मुक्त-पहुँच रिपोर्ट की आकृति 2 है (CC BY 4.0), ऊपर के अंश में दिखाई गई। यह किसी अन्य समीक्षा की आकृति नहीं है।",
        design="एक मामले की रिपोर्ट, यादृच्छिक अध्ययन नहीं। व्यक्ति चिकित्सकीय रूप से स्थिर होने के बाद चिकित्सकों ने न्यूरोफिज़ियोथेरेपी दी जिसमें Syrebo दस्ताना कार्यक्रम शामिल था।",
        sample="द्विपक्षीय MCA क्षेत्र रोधगलन वाली 66 वर्ष की महिला। रिपोर्ट अवलोकन और कार्यात्मक बदलाव दर्ज करती है। अंतर-समूह आँकड़े नहीं देती।",
        result="रिपोर्ट का मूल्य देखभाल का क्रम है, सुधार की दर नहीं। यह दिखाती है कि गंभीर रोधगलन वाले एक व्यक्ति के पुनर्वास में नरम दस्ताना पेशेवर निगरानी में कैसे रखा गया। एक मामले का बदलाव वादा किया गया सुधार-स्तर नहीं है।",
        sig=[
            "अधिकतर यादृच्छिक अध्ययनों वाले कॉलम में एक मामला यह दिखाने के लिए है कि कार्यक्रम एक व्यक्ति पर कैसे उपयोग हुआ। यह कथा का अंतर भरता है। यह साक्ष्य का स्तर नहीं बढ़ाता।",
            "एक मामला यह अनुमान नहीं लगा सकता कि प्रतिकूल घटनाएँ कितनी बार होती हैं, और यह नहीं कह सकता कि तीव्र, उप-तीव्र या दीर्घकालिक चरण अधिक उपयुक्त है। वे प्रश्न नियंत्रित अध्ययनों के पास रहते हैं।",
        ],
        limit="एकल मामला। सामान्य प्रभाव नहीं। कार्यात्मक बदलाव अकेले दस्ताने को नहीं दिया जा सकता।")

    add(8, "hi",
        title="स्ट्रोक के बाद ऊपरी अंग की हानि: नवोन्मेषी मिरर थेरेपी का 60 लोगों का यादृच्छिक अध्ययन",
        desc="New Medicine, 2024: 60 लोग, चार सप्ताह। लेख नवोन्मेषी मिरर थेरेपी में FMA-UE, FMA-WH और संशोधित Barthel सूचकांक पर सामान्य मिरर थेरेपी से अधिक लाभ बताता है।",
        lead="सामान्य मिरर थेरेपी दर्पण से यह आभास देती है कि प्रभावित हाथ हिल रहा है। नवोन्मेषी रूप रोबोटिक दस्ताने से प्रभावित हाथ को वही क्रिया करवाता है जो दर्पण दिखाता है, ताकि देखना और करना सत्र साझा करें। 2024 में New Medicine ने Chen और सहयोगियों का यादृच्छिक अध्ययन छापा जिसने दोनों रूपों की 60 लोगों में चार सप्ताह तुलना की। लेख ऊपरी अंग की गति, कलाई-हाथ की गति और दैनिक गतिविधियों पर नवोन्मेषी मिरर थेरेपी के अधिक लाभ बताता है।",
        bg=[
            "मिरर थेरेपी की ज्ञात सीमा है: यदि प्रभावित हाथ नहीं हिलता, तो दृश्य सुझाव का युग्मित मोटर इनपुट नहीं होता। सहायता प्राप्त मोड़ और फैलाव को मिरर कार्य से जोड़ना यह प्रयास है कि प्रभावित पक्ष चिकित्सक द्वारा तय सीमा के भीतर गति वास्तव में पूरी करे।",
            "वह बदलाव अंकों पर दिखता है या नहीं, यह सामान्य मिरर थेरेपी के विरुद्ध जाँचना होता है, कुछ न करने के विरुद्ध नहीं। साठ लोग, बराबर बाँटे गए, प्रारंभिक यादृच्छिक आकार है।",
        ],
        device="पत्रिका पृष्ठ पर प्रशिक्षण छवि Yisheng (羿生) चिह्न दिखाती है। कॉलम उस चिह्न को आधिकारिक सामग्री के SY-HR08E से जोड़ता है और स्क्रीन, कंसोल व दस्ताने वाली उत्पाद फ़ोटो दिखाता है। यह जोड़ पहचान का नोट है, अध्ययन पंजीकरण की तरह छपा मॉडल-दावा नहीं।",
        design="यादृच्छिक संख्या आवंटन। नवोन्मेषी मिरर थेरेपी, जो मिरर कार्य को रोबोटिक दस्ताने से जोड़ती है, की तुलना सामान्य मिरर थेरेपी से हुई। परिणामों में FMA-UE, FMA-WH और संशोधित Barthel सूचकांक थे।",
        sample="स्ट्रोक के बाद ऊपरी अंग की हानि वाले साठ लोग, प्रत्येक समूह में 30, चार सप्ताह तक।",
        result="लेख नवोन्मेषी मिरर थेरेपी के लिए FMA-UE, FMA-WH और संशोधित Barthel सूचकांक पर अधिक सुधार बताता है। यह अध्ययन का अंतर-समूह वर्णन है। माध्य और P मान इस पृष्ठ पर पुनः नहीं गिने जाते; जब तक पत्रिका पृष्ठ जाँचा जा रहा है, वे आँकड़े लेख के पास रहते हैं।",
        sig=[
            "प्रश्न यह है कि दर्पण से मेल खाती सहायता गति जोड़ने पर अंक केवल दर्पण की तुलना में बदलते हैं या नहीं। साठ लोग प्रारंभिक अंतर देते हैं, घरेलू कार्यक्रम का प्रमाण नहीं।",
            "पत्रिका छवि को SY-HR08E से जोड़ना पाठक को केवल उपकरण पहचानने में मदद करता है। अंक-अंतर स्थिर है या नहीं, यह पूर्ण संख्याओं की स्वतंत्र जाँच का इंतज़ार करता है।",
        ],
        limit="प्रति समूह तीस लोग। अंतर लेख का अनुसरण करते हैं। माध्य और P मान यहाँ पुनः नहीं गिने जाते। मॉडल कड़ी पत्रिका आकृति और आधिकारिक सामग्री के बीच जाँच है।")

    add(9, "hi",
        title="MCA रोधगलन के बाद बायाँ अर्धांगघात: फैराडिक उद्दीपन और रोबोटिक हाथ का एक अभिलेख",
        desc="IJPRCP मामला: बाएँ अर्धांगघात वाला 60 वर्ष का पुरुष स्ट्रोक के लगभग तीन महीने बाद फैराडिक उद्दीपन और Syrebo C12 शुरू करता है, सप्ताह में पाँच बार, चार सप्ताह। एक संयुक्त मामला किसी एक घटक को नहीं दिया जाता।",
        lead="अर्धांगघात वाले हाथ को कभी दो इनपुट एक साथ मिलते हैं: मांसपेशी की ओर विद्युत उद्दीपन, और उँगलियाँ खोलने-बंद करने के लिए रोबोटिक हाथ। International Journal of Physiotherapy Research and Clinical Practice में 2025 का मामला बाएँ अर्धांगघात वाले एक पुरुष में चार सप्ताह के फैराडिक उद्दीपन और Syrebo C12 को दर्ज करता है। यह संयुक्त योजना का अभिलेख है, किसी एक हिस्से का प्रभावशीलता अध्ययन नहीं।",
        bg=[
            "स्ट्रोक के महीनों बाद हाथ का बदलाव आमतौर पर धीमा होता है, और चिकित्सक कभी सामान्य अभ्यास में उद्दीपन या बाहरी सहायता जोड़ते हैं। दोनों के उपयोग के बाद पहले-बाद बदलाव को साफ़-साफ़ किसी एक को नहीं दिया जा सकता।",
            "रिपोर्ट फिर भी उपयोगी है। यह बताती है कि योजना कब शुरू हुई, कितनी बार चली, और कमरे में कौन सा उपकरण था। यह दर नहीं देती, और नियंत्रण के विरुद्ध अंतर नहीं देती।",
        ],
        device="रिपोर्ट में रोबोटिक उपकरण Syrebo C12 है। फ़ोटो आधिकारिक C12 उत्पाद पृष्ठ की कटाई है ताकि कंसोल और दस्ताना पहचाने जाएँ। यह वे विनिर्देश नहीं जोड़ती जिन्हें लेख ने छोड़ा।",
        design="एक संयुक्त हस्तक्षेप: फैराडिक उद्दीपन के साथ Syrebo C12 रोबोटिक हाथ अभ्यास। समानांतर नियंत्रण समूह नहीं है।",
        sample="बाएँ अर्धांगघात वाला 60 वर्ष का पुरुष। योजना स्ट्रोक के 3 महीने 2 सप्ताह बाद शुरू हुई, सप्ताह में पाँच बार, चार सप्ताह तक।",
        result="यह पृष्ठ वे कार्यात्मक अंक फिर नहीं छापता जिन्हें कॉलम के लिए लेख से जाँचा नहीं गया। स्पष्ट व्यवस्था है: उद्दीपन और रोबोटिक अभ्यास साथ उपयोग हुए, इसलिए बदलाव को अकेले C12 या अकेले उद्दीपन का प्रभाव नहीं लिखा जा सकता।",
        sig=[
            "अभिलेख एक ठोस समय-सारणी जोड़ता है: स्ट्रोक के लगभग तीन महीने बाद, सप्ताह में पाँच सत्र, दो विधियाँ साथ। यह साक्ष्य का स्तर नहीं बढ़ाता।",
            "MCA रोधगलन के बाद बाएँ अर्धांगघात का एक मामला अन्य घावों या शुरुआत के अन्य समयों की जगह नहीं लेता।",
        ],
        limit="एकल संयुक्त मामला। बदलाव C12 या उद्दीपन को नहीं दिया जाता, और यह सामान्य प्रभाव नहीं है।")

    add(10, "hi",
        title="नरम कलाई-हाथ ऑर्थोसिस: Wearable Technologies में डिज़ाइन और प्रारंभिक मूल्यांकन",
        desc="Ledoux और Barth Wearable Technologies में अपना 3D-मुद्रित कलाई-हाथ ऑर्थोसिस बताते हैं। यह नोट उसी डिज़ाइन लेख पर रहता है। यह व्यावसायिक उत्पादों की रैंकिंग नहीं करता और प्रभावशीलता अध्ययन नहीं है।",
        lead="2024 में Cambridge University Press की Wearable Technologies ने Vanderbilt विश्वविद्यालय के Ledoux और Barth का डिज़ाइन लेख छापा। जो उपकरण उन्होंने बनाया और प्रारंभिक रूप से आँका, वह उनका अपना 3D-मुद्रित कलाई-हाथ पकड़ ऑर्थोसिस है। लेख पहनने योग्य हाथों की चर्चा में व्यावसायिक नरम संरचनाओं का उल्लेख करता है। यह कॉलम उस चर्चा को रैंकिंग नहीं बनाता, और लेख को Syrebo की प्रभावशीलता का प्रमाण नहीं मानता।",
        bg=[
            "हाथ का उपकरण जो थेरेपी कक्ष छोड़ता है, उसे भार, रूप और इस बात का उत्तर देना होता है कि व्यक्ति उसे पहन सकता है या नहीं। डिज़ाइन लेख आमतौर पर वे सीमाएँ बताते हैं और फिर प्रोटोटाइप का वर्णन करते हैं। वे पहले बहु-केंद्रीय कार्यात्मक अध्ययन नहीं बताते। डिज़ाइन लेख को प्रभावशीलता लेख की तरह पढ़ना ऐसे नैदानिक अंत-बिंदु गढ़ता है जो मापे नहीं गए।",
            "नरम संरचना और कठोर एक्सोस्केलेटन अलग इंजीनियरिंग प्रश्नों का उत्तर देते हैं। कोमलता रूप घटाने का एक तरीका है। कार्यात्मक बदलाव की बात अभी भी अपना मानव अध्ययन माँगती है।",
        ],
        device="ऊपर का अंश मुक्त-पहुँच पहला पृष्ठ है (CC BY 4.0), तुलना तालिका नहीं। उत्पाद फ़ोटो Syrebo नैदानिक दस्ताना प्रणाली दिखाती है। यह इस प्रयोग की आकृति नहीं है।",
        design="लेखकों के अपने 3D-मुद्रित ऑर्थोसिस का डिज़ाइन, मॉडलिंग और प्रारंभिक मूल्यांकन। लेख Syrebo का यादृच्छिक अध्ययन नहीं है और बाज़ार उपकरणों के बीच प्रभावशीलता तुलना नहीं है।",
        sample="मानव हिस्सा लेखकों के प्रोटोटाइप पर प्रारंभिक दृष्टि है। उसका आकार और कार्य लेख के हैं। उसे यहाँ Syrebo कोहॉर्ट के रूप में नहीं लिखा गया।",
        result="यह पृष्ठ व्यावसायिक विशेषण नहीं उद्धृत करता और अन्य ब्रांड नहीं गिनता। जो बचता है वह यह कि लेख नरम, पहनने योग्य संरचना पर मुक्त-पहुँच डिज़ाइन अध्ययन है। लेखकों का शब्द «presumably» आराम को उस चीज़ के रूप में चिह्नित करता है जिसे उन्होंने मापा अंत-बिंदु नहीं माना।",
        sig=[
            "लेख कॉलम में इसलिए है कि डिज़ाइन अध्ययन प्रभावशीलता अध्ययन से अलग रहे। नरम संरचना उपकरण को दैनिक जीवन में पहनना आसान बनाती है या नहीं, यह पहनने का अध्ययन और कार्यात्मक अध्ययन अलग-अलग हैं।",
            "मुक्त पहुँच पाठक को शब्दावली जाँचने देती है। जाँच का उद्देश्य अनुमान को निष्कर्ष बनने से रोकना है, सबसे हल्का उत्पाद चुनना नहीं।",
        ],
        limit="Syrebo का प्रभावशीलता अध्ययन नहीं, और उत्पाद रैंकिंग नहीं। स्रोत आराम को «presumably» से घेरता है। पहले पृष्ठ की कटाई में तुलना तालिका नहीं है।")

    add(11, "hi",
        title="घर के उपयोग के लिए सोचे गए उँगली रोबोट: Journal of the Robotics Society of Japan में विकास टिप्पणी",
        desc="Journal of the Robotics Society of Japan का 2023 लेख अर्धांगघात के लिए घरेलू उँगली रोबोटों की चर्चा करता है और Syrebo को कुछ व्यावसायीकृत उदाहरणों में नाम देता है। यह नैदानिक अध्ययन नहीं है।",
        lead="घर पर हाथ पुनर्वास वर्षों से चर्चा में है। समाज साहित्य में व्यावसायीकृत उदाहरण अभी कम हैं। 2023 में Journal of the Robotics Society of Japan ने Furudate और सहयोगियों का लेख छापा, अर्धांगघात के बाद घरेलू उपयोग के लिए सोचे गए उँगली-पुनर्वास रोबोट पर, और चिकित्सकों के साथ उसके विकास पर। लेखक लिखते हैं कि व्यावसायीकृत घरेलू उपयोग के मामले दुर्लभ हैं, और Syrebo हाथ दस्ताने को ऐसा एक मामला बताते हैं। लेख विकास और सहयोग की टिप्पणी है, प्रभावशीलता अध्ययन नहीं।",
        bg=[
            "वार्ड और घर के बीच पहनना, सुरक्षा सीमाएँ, और वह उपयोग है जब कमरे में चिकित्सक नहीं होता। इंजीनियरिंग लेख उन सीमाओं को चिकित्सकों के साथ काम के भीतर रखते हैं। नाम लिया जाना यह कहता है कि लेखकों ने इस उत्पाद को उदाहरण चुना। इसका अर्थ यह नहीं कि समाज ने नियंत्रित अध्ययन किया।",
            "«कुछ ही व्यावसायीकृत हुए हैं» भी एक सीमा है। इसे «घरेलू पुनर्वास पहले से सामान्य रूप से उपलब्ध है» पढ़ना उदाहरण को महामारीविज्ञान दावा बना देता है।",
        ],
        device="लेख दस्ताना फ़ोटो नहीं छापता। इस कॉलम में दस्ताना और कंसोल की छवि Sharma और सहयोगियों की 2024 Cureus मामले की आकृति 2 है (CC BY 4.0)। कैप्शन ऐसा कहता है। यह जापानी समाज लेख की मूल आकृति नहीं है।",
        design="घरेलू उपयोग के उँगली रोबोटों और चिकित्सकों के साथ काम पर समाज-पत्रिका का विकास लेख। यादृच्छिकीकरण नहीं है और अंतर-समूह कार्यात्मक तुलना नहीं है।",
        sample="नैदानिक नमूना आकार लागू नहीं होता। लेख उत्पाद तक के मार्ग की चर्चा करता है, किसी कोहॉर्ट के परिणामों की नहीं।",
        result="कथन, जैसा यहाँ उपयोग हुआ है, यह है कि घर की ओर व्यावसायीकृत उँगली रोबोट अभी कम हैं, और Syrebo एक उदाहरण है जिसे लेखक नाम देते हैं। कॉलम वह दायरा रखता है। उसे प्रभावशीलता, बाज़ार रैंक, या इस वादे के रूप में नहीं लिखा गया कि घर पर प्रशिक्षण पूरा होगा।",
        sig=[
            "टिप्पणी का मूल्य यह है कि घरेलू उपयोग को चिकित्सकों के साथ परिभाषित इंजीनियरिंग समस्या माना गया है। व्यावसायीकृत उदाहरण दिखाता है कि एक उपकरण प्रोटोटाइप से उत्पाद तक गया।",
            "क्या उसे घर पर सुरक्षित और बार-बार उपयोग किया जा सकता है, यह अभी भी संकेत, निगरानी और अलग नैदानिक अध्ययनों पर निर्भर करता है। समाज लेख वे आँकड़े नहीं देता।",
        ],
        limit="Syrebo का नैदानिक अध्ययन नहीं। स्रोत बल देता है कि व्यावसायीकृत उदाहरण कम हैं। फ़ोटो एक अलग मुक्त-पहुँच मामले से है।")
